window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9d65b55c6003b0f0"]={"versions": [{"id": "FIG-9d65b55c6003b0f0", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECUC-Parametermodells (ECU Configuration Parameter Definition) für das Modul <code>Arti</code>, speziell den Modul- und Subcontainer-Zweig <code>ArtiRte</code>. Es spezifiziert die Metamodellstruktur zur Konfiguration von ARTI-Trace-Hooks bezüglich der RTE auf ECU-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Arti: EcucModuleDef</code> (Multiplizität: 0..1): Wurzel-Moduldefinition.</li>\n<li><code>ArtiRte: EcucParamConfContainerDef</code> (Multiplizität: 0..1): Container zur Konfiguration von ARTI bezüglich der RTE, eingebettet in <code>Arti</code> über die Komposition <code>+container</code>.</li>\n<li><code>ArtiRteHookRef: EcucReferenceDef</code> (Multiplizität: 0..<em>): Referenzdefinition, eingebettet in <code>ArtiRte</code> über die Komposition <code>+reference</code>. Sie verweist über eine gerichtete Assoziation <code>+destination</code> auf das Ziel <code>ArtiHook: EcucParamConfContainerDef</code> (Multiplizität: 0..</em>).</li>\n<li>Untergeordnete Parameter-Container, die per Komposition <code>+subContainer</code> in <code>ArtiRte</code> eingebunden sind:</li>\n<li><code>ArtiRteRunnableClass: EcucParamConfContainerDef</code> (Multiplizität: 0..1)</li>\n<li><code>ArtiRteRunnableInstance: EcucParamConfContainerDef</code> (Multiplizität: 0..1)</li>\n<li><code>ArtiRteSchedulableClass: EcucParamConfContainerDef</code> (Multiplizität: 0..1)</li>\n<li><code>ArtiRteSchedulableInstance: EcucParamConfContainerDef</code> (Multiplizität: 0..1)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell- bzw. Konfigurationsklassendiagramm stellt das Diagramm keine zeitlichen Abläufe oder dynamischen Zustandsübergänge dar. Es definiert die statische Struktur und Schachtelungshierarchie für die Generierung und Validierung der ARTI-RTE-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation der ECUC-Struktur für ARTI-RTE:</p>\n<ul class=\"fig-list\">\n<li>Das Vorhandensein des Containers <code>ArtiRte</code> ist optional (0..1), ebenso wie die Untercontainer <code>ArtiRteRunnableClass</code>, <code>ArtiRteRunnableInstance</code>, <code>ArtiRteSchedulableClass</code> und <code>ArtiRteSchedulableInstance</code> (jeweils 0..1).</li>\n<li><code>ArtiRteHookRef</code> erlaubt beliebig viele Verweise (0..*) auf <code>ArtiHook</code>-Container zur Zuordnung generischer oder spezifischer Hook-Definitionen.</li>\n<li>Ein Konfigurationseditor bzw. Codegenerator muss diese Multiplizitäten und Referenztypen bei der Schema-Validierung und Artefaktgenerierung zwingend einhalten.</li>\n</ul>"}, {"id": "FIG-2d58eeb7c597810e", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECUC-Parametermodells (ECU Configuration Parameter Definition) für das Modul <code>Arti</code>, speziell den Modul- und Subcontainer-Zweig <code>ArtiRte</code>. Es spezifiziert die Metamodellstruktur zur Konfiguration von ARTI-Trace-Hooks bezüglich der RTE auf ECU-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Arti: EcucModuleDef</code> (Multiplizität: 0..1): Wurzel-Moduldefinition.</li>\n<li><code>ArtiRte: EcucParamConfContainerDef</code> (Multiplizität: 0..1): Container zur Konfiguration von ARTI bezüglich der RTE, eingebettet in <code>Arti</code> über die Komposition <code>+container</code>.</li>\n<li><code>ArtiRteHookRef: EcucReferenceDef</code> (Multiplizität: 0..<em>): Referenzdefinition, eingebettet in <code>ArtiRte</code> über die Komposition <code>+reference</code>. Sie verweist über eine gerichtete Assoziation <code>+destination</code> auf das Ziel <code>ArtiHook: EcucParamConfContainerDef</code> (Multiplizität: 0..</em>).</li>\n<li>Untergeordnete Parameter-Container, die per Komposition <code>+subContainer</code> in <code>ArtiRte</code> eingebunden sind:</li>\n<li><code>ArtiRteRunnableClass: EcucParamConfContainerDef</code> (Multiplizität: 0..1)</li>\n<li><code>ArtiRteRunnableInstance: EcucParamConfContainerDef</code> (Multiplizität: 0..1)</li>\n<li><code>ArtiRteSchedulableClass: EcucParamConfContainerDef</code> (Multiplizität: 0..1)</li>\n<li><code>ArtiRteSchedulableInstance: EcucParamConfContainerDef</code> (Multiplizität: 0..1)</li>\n<li><code>ArtiRteVfbTraceHooks: EcucParamConfContainerDef</code> (Multiplizität: 1..1)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell- bzw. Konfigurationsklassendiagramm stellt das Diagramm keine zeitlichen Abläufe oder dynamischen Zustandsübergänge dar. Es definiert die statische Struktur und Schachtelungshierarchie für die Generierung und Validierung der ARTI-RTE-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation der ECUC-Struktur für ARTI-RTE:</p>\n<ul class=\"fig-list\">\n<li>Das Vorhandensein des Containers <code>ArtiRte</code> ist optional (0..1).</li>\n<li>Sofern <code>ArtiRte</code> konfiguriert wird, ist der Untercontainer <code>ArtiRteVfbTraceHooks</code> verpflichtend vorzusehen (Multiplizität 1..1).</li>\n<li>Die Untercontainer <code>ArtiRteRunnableClass</code>, <code>ArtiRteRunnableInstance</code>, <code>ArtiRteSchedulableClass</code> und <code>ArtiRteSchedulableInstance</code> sind optional (jeweils Multiplizität 0..1).</li>\n<li><code>ArtiRteHookRef</code> erlaubt beliebig viele Verweise (0..*) auf <code>ArtiHook</code>-Container zur Zuordnung von Hook-Definitionen.</li>\n<li>Ein Konfigurationseditor bzw. Codegenerator muss diese Multiplizitäten und Referenztypen bei der Schema-Validierung und Artefaktgenerierung zwingend einhalten.</li>\n</ul>"}, {"id": "FIG-404a710942d4fa41", "releases": ["R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECUC-Parametermodells (ECU Configuration Parameter Definition) für das Modul <code>Arti</code>, speziell den Modul- und Subcontainer-Zweig <code>ArtiRte</code>. Es spezifiziert die Metamodellstruktur zur Konfiguration von ARTI-Trace-Hooks bezüglich der RTE auf ECU-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Arti: EcucModuleDef</code> (Multiplizität: 0..1): Wurzel-Moduldefinition.</li>\n<li><code>ArtiRte: EcucParamConfContainerDef</code> (Multiplizität: 0..1): Container zur Konfiguration von ARTI bezüglich der RTE, eingebettet in <code>Arti</code> über die Komposition <code>+container</code>.</li>\n<li><code>ArtiRteHookRef: EcucReferenceDef</code> (Multiplizität: 0..<em>): Referenzdefinition, eingebettet in <code>ArtiRte</code> über die Komposition <code>+reference</code>. Sie verweist über eine gerichtete Assoziation <code>+destination</code> auf das Ziel <code>ArtiHook: EcucParamConfContainerDef</code> (Multiplizität: 0..</em>).</li>\n<li>Untergeordnete Parameter-Container, die per Komposition <code>+subContainer</code> in <code>ArtiRte</code> eingebunden sind:</li>\n<li><code>ArtiRteRunnableClass: EcucParamConfContainerDef</code> (Multiplizität: 0..1)</li>\n<li><code>ArtiRteRunnableInstance: EcucParamConfContainerDef</code> (Multiplizität: 0..1)</li>\n<li><code>ArtiRteSchedulableClass: EcucParamConfContainerDef</code> (Multiplizität: 0..1)</li>\n<li><code>ArtiRteSchedulableInstance: EcucParamConfContainerDef</code> (Multiplizität: 0..1)</li>\n<li><code>ArtiRteVfbTraceHooks: EcucParamConfContainerDef</code> (Multiplizität: 1..1)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell- bzw. Konfigurationsklassendiagramm stellt das Diagramm keine zeitlichen Abläufe oder dynamischen Zustandsübergänge dar. Es definiert die statische Struktur und Schachtelungshierarchie für die Generierung und Validierung der ARTI-RTE-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation der ECUC-Struktur für ARTI-RTE:</p>\n<ul class=\"fig-list\">\n<li>Das Vorhandensein des Containers <code>ArtiRte</code> ist optional (0..1).</li>\n<li>Sofern <code>ArtiRte</code> konfiguriert wird, ist der Untercontainer <code>ArtiRteVfbTraceHooks</code> verpflichtend vorzusehen (Multiplizität 1..1).</li>\n<li>Die Untercontainer <code>ArtiRteRunnableClass</code>, <code>ArtiRteRunnableInstance</code>, <code>ArtiRteSchedulableClass</code> und <code>ArtiRteSchedulableInstance</code> sind optional (jeweils Multiplizität 0..1).</li>\n<li><code>ArtiRteHookRef</code> erlaubt beliebig viele Verweise (0..*) auf <code>ArtiHook</code>-Container zur Zuordnung von Hook-Definitionen.</li>\n<li>Ein Konfigurationseditor bzw. Codegenerator muss diese Multiplizitäten und Referenztypen bei der Schema-Validierung und Artefaktgenerierung zwingend einhalten.</li>\n</ul>"}], "trans": [{"from": "FIG-9d65b55c6003b0f0", "to": "FIG-2d58eeb7c597810e", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Sub-Container <code>ArtiRteVfbTraceHooks</code> (Typ <code>EcucParamConfContainerDef</code>) mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code> als verpflichtender Untercontainer unter <code>ArtiRte</code> über Kompositionsbeziehung <code>+subContainer</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-2d58eeb7c597810e", "to": "FIG-404a710942d4fa41", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
